_REVIEW_OMEGA = '[[package]]\nname = "omega"\nversion = "1.0.0"\n\n'
_REVIEW_METADATA = (
    '[metadata]\nlock-version = "2.1"\npython-versions = ">=3.12,<3.14"\n'
    'content-hash = "' + "a" * 64 + '"\n'
)
_REVIEW_LEARNING = (
    '[[package]]\nname = "dotmac-learning"\nversion = "0.1.0a1"\n'
    'description = "Reusable tenant learning results, progress, '
    'completion and certificates"\n'
    'optional = false\npython-versions = ">=3.11,<3.14"\ngroups = ["main"]\n'
    "files = []\ndevelop = true\n\n[package.dependencies]\n"
    'alembic = ">=1.13"\ndotmac-kernel = ">=0.1.0a106"\n'
    'pydantic = "^2.9"\nsqlalchemy = "^2.0"\n\n[package.source]\n'
    'type = "directory"\nurl = "packages/dotmac-learning"\n\n\n'
)


def _review_document():
    document = _document_v2()
    document["files"][-1] = _file(
        PACKAGE + "pyproject.toml",
        LEARNING_V2
        + 'version = "0.1.0a1"\n'
        + 'description = "Reusable tenant learning results, progress, '
        'completion and certificates"\n'
        + '[tool.poetry.dependencies]\npython = ">=3.11,<3.14"\n'
        + 'dotmac-kernel = ">=0.1.0a106"\nsqlalchemy = "^2.0"\n'
        + 'pydantic = "^2.9"\nalembic = ">=1.13"\n',
    )
    for name, version in (
        ("dotmac-fulfillment", "0.1.0a2"),
        ("dotmac-template-studio", "0.2.0a6"),
    ):
        path = f"packages/{name}/pyproject.toml"
        index = next(
            i for i, item in enumerate(document["files"]) if item["path"] == path
        )
        document["files"][index] = _file(
            path,
            f'[tool.poetry]\nname = "{name}"\nversion = "{version}"\n'
            '[tool.poetry.dependencies]\ndotmac-kernel = ">=0.1.0a106"\n',
            hashlib.sha256(EXISTING_V2[path].encode()).hexdigest(),
        )
    return document


def _review_locks():
    base = (
        _REVIEW_HEADER
        + _REVIEW_ALPHA
        + _REVIEW_FU
        + _REVIEW_TS
        + _REVIEW_OMEGA
        + _REVIEW_METADATA
    )
    generated = (
        _REVIEW_HEADER
        + _REVIEW_ALPHA
        + _REVIEW_FU.replace('version = "0.1.0a1"', 'version = "0.1.0a2"').replace(
            "0.1.0a89", "0.1.0a106"
        )
        + _REVIEW_LEARNING
        + _REVIEW_TS.replace('version = "0.2.0a5"', 'version = "0.2.0a6"').replace(
            "0.1.0a97", "0.1.0a106"
        )
        + _REVIEW_OMEGA
        + _REVIEW_METADATA.replace("a" * 64, "b" * 64)
    )
    return base.encode(), generated.encode()


def test_review_four_operations_independently_reconstruct_every_generated_byte(
    monkeypatch,
):
    base, generated = _review_locks()
    monkeypatch.setattr(
        producer, "_REVIEW_BASE_SHA256", hashlib.sha256(base).hexdigest()
    )
    operations = producer._review_operations(
        base, generated, _proposal(_review_document())
    )
    assert {item["kind"] for item in operations} == {
        "dotmac-fulfillment",
        "dotmac-template-studio",
        "insert-dotmac-learning",
        "metadata-content-hash",
    }
    assert len(operations) == 4
    rebuilt = base
    for item in reversed(operations):
        offset, length = item["offset"], item["old_length"]
        assert (
            hashlib.sha256(base[offset : offset + length]).hexdigest()
            == item["old_sha256"]
        )
        rebuilt = (
            rebuilt[:offset] + item["replacement"].encode() + rebuilt[offset + length :]
        )
    assert rebuilt == generated
    assert hashlib.sha256(rebuilt).digest() == hashlib.sha256(generated).digest()


@pytest.fixture
def review_case(checkout_v2, monkeypatch):
    repo, context = checkout_v2
    base, generated = _review_locks()
    document = _review_document()
    raw = json.dumps(document).encode()
    proposal_path = repo / producer.PROPOSAL_PATH
    proposal_path.parent.mkdir(parents=True)
    proposal_path.write_bytes(raw)
    (repo / "poetry.lock").write_bytes(base)
    prior_git = producer._git
    calls = []

    def git(root, arguments):
        calls.append(arguments)
        result = prior_git(root, arguments)
        if arguments == ("ls-files", "-z", "--cached"):
            result += producer.PROPOSAL_PATH.encode() + b"\0"
        return result

    monkeypatch.setattr(producer, "_git", git)
    monkeypatch.setattr(
        producer, "_REVIEW_BASE_SHA256", hashlib.sha256(base).hexdigest()
    )
    monkeypatch.setattr(
        producer, "_REVIEW_PROPOSAL_SHA256", hashlib.sha256(raw).hexdigest()
    )
    proposal = _proposal(document)
    observed = producer.validate_checkout(repo, proposal, context)
    receipt = producer.LockGenerationManifest(
        2,
        "generated_unqualified_lock",
        "dotmac-learning",
        BASE,
        HEAD,
        (BASE,),
        hashlib.sha256(raw).hexdigest(),
        tuple(
            producer.ProposedFileHash(item.path, item.before_sha256, item.sha256)
            for item in proposal.files + proposal.package_sources
        ),
        "2.4.1",
        observed.original_lock_sha256,
        hashlib.sha256(generated).hexdigest(),
    )
    from dataclasses import asdict

    output = repo / producer.OUTPUT_PATH
    output.mkdir()
    (output / "poetry.lock").write_bytes(generated)
    receipt_path = output / "manifest.json"
    receipt_path.write_text(
        json.dumps(asdict(receipt), sort_keys=True, indent=2) + "\n"
    )
    return repo, output, proposal_path, calls


def test_review_emits_one_bounded_packet_without_generation_or_writes(
    review_case, monkeypatch, capsys
):
    repo, _, _, calls = review_case
    before = {
        str(path): path.read_bytes() for path in repo.rglob("*") if path.is_file()
    }
    monkeypatch.setattr(
        producer, "produce_lock", lambda *args: pytest.fail("generation in review")
    )
    monkeypatch.setattr(
        producer,
        "_command",
        lambda *args, **kwargs: pytest.fail("tool command in review"),
    )
    monkeypatch.setattr(
        Path, "write_bytes", lambda *args: pytest.fail("write in review")
    )
    monkeypatch.setattr(
        Path, "write_text", lambda *args, **kwargs: pytest.fail("write in review")
    )
    producer._review_artifact(repo)
    captured = capsys.readouterr()
    lines = captured.out.splitlines()
    assert lines[0] == producer._REVIEW_BEGIN and lines[2] == producer._REVIEW_END
    assert len(lines) == 3 and captured.err == ""
    packet = json.loads(lines[1])
    assert packet["purpose"] == "UNQUALIFIED" and len(packet["operations"]) == 4
    assert len(lines[1]) <= producer._REVIEW_PACKET_LIMIT and lines[1].isascii()
    assert packet["receipt"]["checkout_sha"] == HEAD
    assert (
        packet["generated_lock"]["sha256"]
        == hashlib.sha256(_review_locks()[1]).hexdigest()
    )
    assert calls.count(("diff", "--quiet", "HEAD", "--")) >= 2
    assert before == {
        str(path): path.read_bytes() for path in repo.rglob("*") if path.is_file()
    }


@pytest.mark.parametrize(
    "mutation",
    [
        "unrelated_byte",
        "order",
        "extra_package",
        "extra_root",
        "duplicate_package",
        "header",
        "learning_comment",
        "learning_url",
        "learning_key",
        "learning_dependency",
        "learning_version",
        "metadata_python",
        "metadata_version",
        "metadata_extra",
        "metadata_hash",
        "fu_extra",
        "ts_extra",
    ],
)
def test_review_rejects_nonwhitelisted_lock_bytes_without_printing_payload(
    review_case, mutation, capsys
):
    repo, output, _, _ = review_case
    path = output / "poetry.lock"
    generated = path.read_text()
    if mutation == "unrelated_byte":
        generated = generated.replace('name = "alpha"', f'name = "{_REVIEW_SENTINEL}"')
    elif mutation == "order":
        generated = generated.replace(_REVIEW_ALPHA, "").replace(
            _REVIEW_OMEGA, _REVIEW_OMEGA + _REVIEW_ALPHA
        )
    elif mutation in {"extra_package", "duplicate_package"}:
        name = _REVIEW_SENTINEL if mutation == "extra_package" else "alpha"
        generated = generated.replace(
            "[metadata]", f'[[package]]\nname = "{name}"\n\n[metadata]'
        )
    elif mutation == "extra_root":
        generated += '\n[private]\nvalue = "' + _REVIEW_SENTINEL + '"\n'
    elif mutation == "header":
        generated = generated.replace(
            "generated by Poetry", f"{_REVIEW_SENTINEL} by Poetry"
        )
    elif mutation.startswith("learning_"):
        replacement = _REVIEW_LEARNING
        if mutation == "learning_comment":
            replacement += "# " + _REVIEW_SENTINEL + "\n"
        elif mutation == "learning_url":
            replacement = replacement.replace(
                "packages/dotmac-learning", "https://" + _REVIEW_SENTINEL
            )
        elif mutation == "learning_key":
            replacement = replacement.replace(
                "optional = false", f'private = "{_REVIEW_SENTINEL}"\noptional = false'
            )
        elif mutation == "learning_dependency":
            replacement = replacement.replace(
                "[package.dependencies]",
                '[package.dependencies]\nprivate = "' + _REVIEW_SENTINEL + '"',
            )
        else:
            replacement = replacement.replace(
                'version = "0.1.0a1"', 'version = "' + _REVIEW_SENTINEL + '"'
            )
        generated = generated.replace(_REVIEW_LEARNING, replacement)
    elif mutation == "metadata_python":
        generated = generated.replace(
            'python-versions = ">=3.12,<3.14"',
            'python-versions = "' + _REVIEW_SENTINEL + '"',
        )
    elif mutation == "metadata_version":
        generated = generated.replace(
            'lock-version = "2.1"', 'lock-version = "' + _REVIEW_SENTINEL + '"'
        )
    elif mutation == "metadata_extra":
        generated += 'private = "' + _REVIEW_SENTINEL + '"\n'
    elif mutation == "metadata_hash":
        generated = generated.replace("b" * 64, _REVIEW_SENTINEL)
    else:
        package = (
            "dotmac-fulfillment" if mutation == "fu_extra" else "dotmac-template-studio"
        )
        generated = generated.replace(
            'name = "' + package + '"',
            'name = "' + package + '"\nprivate = "' + _REVIEW_SENTINEL + '"',
        )
    path.write_text(generated)
    # Keep the receipt internally consistent: only the lock whitelist can refuse.
    receipt_path = output / "manifest.json"
    receipt = json.loads(receipt_path.read_bytes())
    receipt["lock_sha256"] = hashlib.sha256(generated.encode()).hexdigest()
    receipt_path.write_text(json.dumps(receipt, sort_keys=True, indent=2) + "\n")
    with pytest.raises(producer.BootstrapError) as caught:
        producer._review_artifact(repo)
    captured = capsys.readouterr()
    assert captured.out == captured.err == ""
    assert _REVIEW_SENTINEL not in str(caught.value)


@pytest.mark.parametrize(
    "mutation",
    [
        "checkout",
        "input",
        "source",
        "base_digest",
        "new_digest",
        "extra",
        "duplicate_json",
    ],
)
def test_review_requires_exact_canonical_receipt_bytes(review_case, mutation, capsys):
    repo, output, _, _ = review_case
    path = output / "manifest.json"
    receipt = json.loads(path.read_bytes())
    if mutation == "source":
        receipt["proposed_files"][-1]["sha256"] = "0" * 64
    elif mutation == "extra":
        receipt["private"] = _REVIEW_SENTINEL
    elif mutation == "duplicate_json":
        path.write_text(
            path.read_text().replace(
                "{\n",
                '{\n  "purpose": "' + _REVIEW_SENTINEL + '",\n',
                1,
            )
        )
    else:
        key = {
            "checkout": "checkout_sha",
            "input": "input_sha256",
            "base_digest": "original_lock_sha256",
            "new_digest": "lock_sha256",
        }[mutation]
        receipt[key] = _REVIEW_SENTINEL
    if mutation != "duplicate_json":
        path.write_text(json.dumps(receipt, sort_keys=True, indent=2) + "\n")
    with pytest.raises(producer.BootstrapError) as caught:
        producer._review_artifact(repo)
    captured = capsys.readouterr()
    assert captured.out == captured.err == ""
    assert _REVIEW_SENTINEL not in str(caught.value)


@pytest.mark.parametrize(
    "mutation",
    [
        "lock_symlink",
        "manifest_symlink",
        "directory_symlink",
        "missing_lock",
        "missing_manifest",
        "dirty_checkout",
        "proposal_hash",
        "base_hash",
        "pin",
        "late_dirty",
    ],
)
def test_review_refuses_input_paths_pins_and_checkout_changes_before_packet(
    review_case, monkeypatch, mutation, capsys
):
    repo, output, proposal_path, calls = review_case
    if mutation.endswith("symlink"):
        if mutation == "directory_symlink":
            target = repo / "private-artifact"
            output.rename(target)
            output.symlink_to(target, target_is_directory=True)
        else:
            path = output / (
                "poetry.lock" if mutation == "lock_symlink" else "manifest.json"
            )
            target = output / "private-target"
            path.rename(target)
            path.symlink_to(target)
    elif mutation.startswith("missing_"):
        (
            output / ("poetry.lock" if mutation == "missing_lock" else "manifest.json")
        ).unlink()
    elif mutation == "dirty_checkout":
        (repo / "pyproject.toml").write_text(ROOT + "# " + _REVIEW_SENTINEL)
    elif mutation == "proposal_hash":
        proposal_path.write_bytes(proposal_path.read_bytes() + b" ")
        receipt_path = output / "manifest.json"
        receipt = json.loads(receipt_path.read_bytes())
        receipt["input_sha256"] = hashlib.sha256(proposal_path.read_bytes()).hexdigest()
        receipt_path.write_text(json.dumps(receipt, sort_keys=True, indent=2) + "\n")
    elif mutation == "base_hash":
        base_path = repo / "poetry.lock"
        generated_path = output / "poetry.lock"
        for path in (base_path, generated_path):
            path.write_bytes(
                path.read_bytes().replace(b'name = "alpha"', b'name = "aardvark"')
            )
        receipt_path = output / "manifest.json"
        receipt = json.loads(receipt_path.read_bytes())
        receipt["original_lock_sha256"] = hashlib.sha256(
            base_path.read_bytes()
        ).hexdigest()
        receipt["lock_sha256"] = hashlib.sha256(generated_path.read_bytes()).hexdigest()
        receipt_path.write_text(json.dumps(receipt, sort_keys=True, indent=2) + "\n")
    elif mutation == "pin":
        (repo / ".github/bootstrap/poetry-requirements-py312.txt").write_text(
            "poetry==2.3.1\n"
        )
    else:
        prior_git = producer._git
        diffs = 0

        def git(root, arguments):
            nonlocal diffs
            if arguments == ("diff", "--quiet", "HEAD", "--"):
                diffs += 1
                if diffs == 2:
                    raise producer.BootstrapError(_REVIEW_SENTINEL)
            return prior_git(root, arguments)

        monkeypatch.setattr(producer, "_git", git)
    calls.clear()
    with pytest.raises(producer.BootstrapError) as caught:
        producer._review_artifact(repo)
    captured = capsys.readouterr()
    assert captured.out == captured.err == ""
    assert _REVIEW_SENTINEL not in str(caught.value)


def test_review_cli_modes_are_exclusive_and_workflow_reviews_before_upload(monkeypatch):
    monkeypatch.setattr(
        producer.sys, "argv", ["python_lock_bootstrap", "--validate", "--review"]
    )
    with pytest.raises(SystemExit) as caught:
        producer.main()
    assert caught.value.code == 2
    workflow = (
        Path(__file__).parents[2] / ".github/workflows/python-lock-bootstrap.yml"
    ).read_text()
    assert workflow.index("--review") > workflow.index(
        "run: python -m scripts.python_lock_bootstrap\n"
    )
    assert workflow.index("--review") < workflow.index("uses: actions/upload-artifact@")
    assert "contents: read" in workflow and "contents: write" not in workflow


def test_review_cli_dispatches_only_to_read_only_review(review_case, monkeypatch):
    repo, _, _, _ = review_case
    reviewed = []
    monkeypatch.chdir(repo)
    monkeypatch.setattr(producer.sys, "argv", ["python_lock_bootstrap", "--review"])
    monkeypatch.setattr(producer, "_review_artifact", reviewed.append)
    monkeypatch.setattr(
        producer, "produce_lock", lambda *args: pytest.fail("generation")
    )
    assert producer.main() == 0
    assert reviewed == [repo]


